          Empowering freelancers with AI-powered tools to win more clients and
          grow their careers.
        </p>

        <hr />

        <p className="copyright">
          © 2026 Mufasa Developers. All Rights Reserved.
        </p>
      </div>
    </footer>
  );
}

export default Footer;
